    { "Asennon ”{0} / {1}” muuntaminen epäonnistui.", "Failed to convert pose “{0} / {1}”." },
    { "Asennot", "Poses" },
    { "Asennot: {0} bittiä + lisätoiminnot: {1} bittiä / tämän avatarin asentotyökalut", "Poses: {0} bits + optional features: {1} bits / pose tools on this avatar" },
    { "Asento {0}", "Pose {0}" },
    { "Asentojen IK-luettelo", "Pose IK Catalog" },
    { "Asentojen luontia ei voitu aloittaa asetusvirheiden vuoksi.", "Pose generation could not start because of configuration errors." },
    { "Asentojen luontia ei voitu aloittaa, koska Unity-skriptien kääntäminen epäonnistui.", "Pose generation could not start because Unity script compilation failed." },
    { "Asentojen luontia kutsuttiin uudelleen sen ollessa jo käynnissä.", "Pose generation was called again while already running." },
