    { "Aucun", "None" },
    { "Aucun Animator Controller n'est attribué à l'Animator de pose commun.", "The shared posing Animator has no assigned Animator Controller." },
    { "Aucun Animator de pose commun actif n'a été trouvé.", "No active shared posing Animator was found." },
    { "Aucun Humanoid Animator valide n'a été trouvé.", "No valid Humanoid Animator was found." },
    { "Aucun VRC Avatar Descriptor n'a été trouvé parmi les parents de l'outil.", "No VRC Avatar Descriptor was found above the tool." },
    { "Aucun avatar doté d'un Animator n'a été trouvé.", "No avatar with an Animator was found." },
    { "Aucun avatar doté d'un Humanoid Animator n'a été trouvé.", "No avatar with a Humanoid Animator was found." },
