    { "Generování póz nelze spustit kvůli selhání kompilace skriptů Unity.", "Pose generation could not start because Unity script compilation failed." },
    { "Generování přetáčení vyžaduje platného avatara Humanoid.", "Generating roll over requires a valid Humanoid avatar." },
    { "Generowanie obracania wymaga prawidłowego awatara Humanoid.", "Generating roll over requires a valid Humanoid avatar." },
    { "Generowanie póz zostało wywołane ponownie w trakcie działania.", "Pose generation was called again while already running." },
    { "Generuj ikony poz", "Generate pose icons" },
    { "Generuje ustawienia wcześniej, aby skrócić budowanie awatara.", "Generate settings in advance to shorten avatar builds." },
    { "Generér positurikoner", "Generate pose icons" },
    { "Genindlæs", "Reload" },
    { "Genindlæs alt", "Reload all" },
    { "Genindlæs justeringsværdier for alle positurer? Ændringer, der ikke er gemt, går tabt.", "Reload adjustment values for every pose? Unsaved changes will be lost." },
    { "Genindlæser alle justeringsværdier fra de gemte filer.", "Reloads all adjustment values from their saved files." },
    { "Genişletilmiş", "Extended" },
    { "Gennemgå indstillingerne, eller opdatér forberegningen. Se Inspector.", "Review the settings or update the prebuild. Check the Inspector." },
    { "Genskaber alle positurminiaturer. Det kan tage tid afhængigt af antallet af positurer.\nVent, til opdateringen er færdig, før du fortsætter med at bruge Unity.", "Recreate all pose thumbnails. This may take some time depending on the number of poses.\nWait until the update finishes before using Unity." },
    { "Gera as configurações antecipadamente para reduzir o tempo de compilação do avatar.", "Generate settings in advance to shorten avatar builds." },
    { "Gerakan saat ini bukan AnimationClip. Selisih penyesuaian hanya mendukung AnimationClip.", "The current motion is not an AnimationClip. Adjustment deltas support AnimationClips only." },
    { "Gerakkan seluruh tubuh termasuk kepala hingga 3 m ke atas atau bawah. Tinggi lantai netral pada 50%.", "Move your whole body, including your head, up or down by up to 3 m. Floor Height is neutral at 50%." },
    { "Gerar ícones das poses", "Generate pose icons" },
    { "Gereedschap toegevoegd. De lijst met voorinstellingen kon niet worden geladen. Probeer Opnieuw laden onder Avatarinstellingen.", "Tool added. The preset list could not be loaded. Try Reload under Avatar Setup." },
    { "Gereedschapspakket niet gevonden [PS041]", "Tool package not found [PS041]" },
    { "Gereedschapsprefab niet gevonden [PS041]", "Tool prefab not found [PS041]" },
    { "Gerekli Unity sürümü: {0}.{1}+", "Required Unity version: {0}.{1}+" },
