    { "Gesamte Beinlänge (Ober- + Unterschenkel)", "Full leg length (upper + lower)" },
    { "Geschikt voor avatar", "Compatible with avatar" },
    { "Geselecteerde typen gebruiken deze bewegingen. Andere typen behouden hun oorspronkelijke instellingen.", "Selected types use these motions. Other types keep their original settings." },
    { "Gesichert — entfernen", "Backed up — remove" },
    { "Gesichert — löschen", "Backed up — delete" },
