    { "Luo optimoinnin vertailukopio", "Create optimization comparison copy" },
    { "Luo yksi tiedosto tuotetta kohti; nämä ovat erillään avatarikohtaisista asetuksista.", "Create one file per product; it is separate from per-avatar settings." },
    { "Luokan {0} kohdalla {1} ({2}) ei ole animaatiota.", "Item {1} ({2}) in {0} has no animation." },
    { "Luokan {0} kohdalla {1} ({2}) on oma kuvake käytössä, mutta sille ei ole määritetty kuvaa.", "A custom icon is enabled for item {1} ({2}) in {0}, but no image is assigned." },
    { "Luokan {0} kohdalta {1} ({2}) puuttuu Motion Time -parametrin nimi.", "Item {1} ({2}) in {0} has no Motion Time parameter name." },
    { "Luokan {0} kohdan {1} ({2}) Käänny-toiminto vaatii Humanoid AnimationClip -leikkeen.", "Roll over for item {1} ({2}) in {0} requires a Humanoid AnimationClip." },
    { "Luokan {0} kohdan {1} ({2}) kosketuskorjauksen voimakkuus on sallitun alueen ulkopuolella.", "The contact-correction strength for item {1} ({2}) in {0} is out of range." },
    { "Luokan {0} kohdan {1} asentotiedot puuttuvat.", "Pose data for item {1} in {0} is missing." },
    { "Luokan {0} kohta {1} ({2}) käyttää Legacy-animaatiota.", "Item {1} ({2}) in {0} uses a Legacy animation." },
    { "Luokassa {0} ei ole käytössä yhtään asentoa. Sen asennonvalintavalikkoa ei luoda.", "No poses are enabled in {0}. Its pose-selection menu will not be generated." },
