    { "Tidak ada pose aktif dalam {0}. Menu pemilihan kategori ini tidak akan dibuat.", "No poses are enabled in {0}. Its pose-selection menu will not be generated." },
    { "Tidak ada pose avatar acuan yang didaftarkan untuk produk ini.", "No reference avatar pose is registered for this product." },
    { "Tidak ada prasetel yang cocok.", "No matching presets." },
    { "Tidak dapat melakukan prabuild. Periksa penempatan avatar, Animator, dan Humanoid pada pemeriksaan pengaturan di Inspector.", "Cannot prebuild. Check avatar placement, Animator and Humanoid settings under Check settings in the Inspector." },
    { "Tidak dapat membuat {1} untuk state “{0}”.", "Could not create {1} for state “{0}”." },
