    { "ניסיוני", "Experimental" },
    { "ניפוי שגיאות: תצוגה מקדימה של תיקון אווטאר", "Debug: preview avatar correction" },
    { "ניקוי\nPrefabsHashes", "Clear\nPrefabsHashes" },
    { "ניקוי\nPrefabsNames", "Clear\nPrefabsNames" },
