    { "Could not bake IK", "تعذر تثبيت نتيجة IK" },
    { "Could not calculate ViewPosition. Check the scales of bones leading to Head and the Humanoid settings.", "تعذر حساب ViewPosition. افحص مقاييس العظام المؤدية إلى Head وإعدادات Humanoid." },
    { "Could not complete {0}", "تعذر إكمال {0}" },
    { "Could not create {1} for state “{0}”.", "تعذر إنشاء {1} للحالة «{0}»." },
    { "Could not determine the destination folder. Make sure Unity recognizes this project folder: {0}", "تعذر تحديد مجلد الوجهة. تأكد من أن Unity يتعرف على مجلد المشروع هذا: {0}" },
    { "Could not identify VRChat's default idle animation. Check the VRChat SDK.", "تعذّر تحديد حركة الخمول الافتراضية في VRChat. تحقق من VRChat SDK." },
    { "Could not identify the owning scene.", "تعذّر تحديد المشهد المالك." },
    { "Could not isolate the breathing Controller in a copy for generation.", "تعذّر فصل Controller التنفس في نسخة مخصصة للإنشاء." },
    { "Could not load prefab [PS042]", "تعذر تحميل Prefab [PS042]" },
    { "Could not load preset", "تعذر تحميل الإعداد المسبق" },
    { "Could not load the preset list. Choose Reload to try again:", "تعذر تحميل قائمة الإعدادات المسبقة. اختر «إعادة التحميل» للمحاولة مجددًا:" },
    { "Could not measure RootT displacement for roll-over head centering.", "تعذّر قياس إزاحة RootT لمحاذاة الرأس إلى الوسط عند التقلب." },
    { "Could not measure a valid fixed length from the avatar scale.", "تعذر قياس طول ثابت صالح من مقياس الأفاتار." },
    { "Could not measure a valid length between {0} and {1}.", "تعذر قياس طول صالح بين {0} و{1}." },
    { "Could not measure the depth difference between Head and Viewpoint. Check View Position and the avatar scale.", "تعذر قياس فرق العمق بين Head وViewpoint. افحص View Position ومقياس الأفاتار." },
    { "Could not measure the height difference between Head and Viewpoint. Check View Position and the avatar scale.", "تعذر قياس فرق الارتفاع بين Head وViewpoint. افحص View Position ومقياس الأفاتار." },
    { "Could not move the generated file to the trash: {0}", "تعذّر نقل الملف المُنشأ إلى سلة المهملات: {0}" },
    { "Could not obtain the Head reference pose used for ViewPosition.", "تعذر الحصول على الوضعية المرجعية لـHead المستخدمة في ViewPosition." },
    { "Could not obtain the Head rotation used as the ViewPosition reference.", "تعذر الحصول على دوران Head المستخدم مرجعًا لـViewPosition." },
    { "Could not obtain the Humanoid reference axes for {0}.", "تعذر الحصول على محاور Humanoid المرجعية لـ{0}." },
    { "Could not place prefab [PS043]", "تعذر وضع Prefab [PS043]" },
