    { "The pose tool reported the following error. How can I resolve it?", "כלי התנוחות דיווח על השגיאה הבאה. איך אפשר לפתור אותה?" },
    { "The prefab is damaged or has no Posing System component. Check the Console for Missing Script and compilation errors.", "ה-prefab פגום או שאין בו רכיב Posing System. בדקו Missing Script ושגיאות הידור ב-Console." },
    { "The prefab is damaged or has no Posing System component. Check the Console for missing scripts and compilation errors.", "ה-prefab פגום או שאין בו רכיב Posing System. בדקו סקריפטים חסרים ושגיאות הידור ב-Console." },
    { "The preset was removed or is incompatible with this tool. Select Reload in the Inspector.", "התצורה המוכנה הוסרה או אינה תואמת לכלי הזה. בחרו טעינה מחדש ב-Inspector." },
    { "The previous operation did not finish.", "הפעולה הקודמת לא הושלמה." },
    { "The product that uses these IK settings.", "המוצר שמשתמש בהגדרות ה-IK האלה." },
    { "The reference avatar has no valid Humanoid Animator.", "לאווטאר הייחוס אין Humanoid Animator תקין." },
    { "The reference pose before IK correction.", "תנוחת הייחוס לפני תיקון IK." },
    { "The reference used to measure hand or foot placement, such as Head, Hips, a knee, or ViewPosition (eye position). ViewPosition follows head movement.", "הייחוס למדידת מיקום כף יד או כף רגל, כגון Head, Hips, ברך או ViewPosition (מיקום העיניים). ViewPosition עוקב אחרי תנועת הראש." },
    { "The registry key was kept because other Unisaki Studio product licenses remain.", "הרישיונות האחרים יישמרו." },
    { "The settings on object {0} have changed. Update the prebuild.", "ההגדרות של האובייקט {0} השתנו. עדכנו את החישוב המקדים." },
    { "The shared Controller has no USSPS_Locomotion layer.", "ב-Controller המשותף חסרה השכבה USSPS_Locomotion." },
    { "The shared Controller has no USSPS_LocomotionType layer.", "ב-Controller המשותף חסרה השכבה USSPS_LocomotionType." },
    { "The shared controller does not match this version's generation definition. Save custom changes in a separate controller, then reinstall the same version of Unisaki Posing System using ALCOM or VCC.", "ה-Controller המשותף אינו תואם להגדרת היצירה של הגרסה הזאת. שמרו שינויים מותאמים ב-Controller נפרד, ואז התקינו שוב את אותה גרסה של Unisaki Posing System דרך ALCOM או VCC." },
    { "The shared controller has no pose-control layers.", "ב-Controller המשותף אין שכבות לשליטה בתנוחות." },
    { "The shared controller has unsaved changes. Save them before trying again.", "ב-Controller המשותף יש שינויים שלא נשמרו. שמרו אותם לפני ניסיון נוסף." },
    { "The shared posing Animator has no MA Merge Animator.", "ב-Animator המשותף לתנוחות חסר MA Merge Animator." },
    { "The shared posing Animator has no assigned Animator Controller.", "ל-Animator המשותף לתנוחות לא משויך Animator Controller." },
    { "The shared posing Animator is missing.", "ה-Animator המשותף לתנוחות חסר." },
    { "The shared posing Animator requires a regular Animator Controller.", "ה-Animator המשותף לתנוחות דורש Animator Controller רגיל." },
    { "The source PosingSystem could not be found.", "PosingSystem המקורי לא נמצא." },
    { "The source pose AnimationClip is missing.", "AnimationClip של תנוחת המקור חסר." },
    { "The standard Controller could not be found in the package.", "ה-Controller התקני לא נמצא בחבילה." },
    { "The standard Controller needed to restore the original poses was not found.", "לא נמצא Controller ברירת המחדל הדרוש לשחזור התנוחות המקוריות." },
    { "The standard PosingSystemLocomotion.controller could not be found, so its reference cannot be restored.", "הקובץ הסטנדרטי PosingSystemLocomotion.controller לא נמצא, ולכן אי אפשר לשחזר את ההפניה אליו." },
    { "The standard prefab will be used to recreate it during prebuild or avatar build.", "הוא ייווצר מחדש מה-prefab התקני במהלך החישוב המקדים או בניית האווטאר." },
    { "The target avatar was not found.", "אוואטר היעד לא נמצא." },
