    { "Install Cool Posing license", "உரிமம் நிறுவல் - Cool Posing" },
    { "Install Kawaii Posing license", "உரிமம் நிறுவல் - Kawaii Posing" },
    { "Install Posing System license", "உரிமம் நிறுவல் - Posing System" },
    { "Install licenses for Cool Posing and Unisaki Posing System on this computer?", "இந்தக் கணினியில் Cool Posing மற்றும் Unisaki Posing System உரிமங்களை நிறுவவா?" },
    { "Install licenses for Kawaii Posing and Unisaki Posing System on this computer?", "இந்தக் கணினியில் Kawaii Posing மற்றும் Unisaki Posing System உரிமங்களை நிறுவவா?" },
    { "Installing package failed due to conflicts:", "தொகுப்பு முரண்பாடுகள்" },
    { "Installing...", "நிறுவுகிறது…" },
    { "Instructions:\n1. Copy one item per line to the clipboard.\n2. Click the matching button.\n3. Duplicates are skipped.", "வழிமுறைகள்:\n1. வரிக்கு ஓர் உருப்படியாக ஒட்டுப்பலகைக்கு நகலெடுக்கவும்.\n2. பொருத்தமான பொத்தானை அழுத்தவும்.\n3. நகல்கள் தவிர்க்கப்படும்." },
    { "Integrate tracking locks with other tools", "பிற கருவிகளுடன் கண்காணிப்புப் பூட்டுகளை ஒருங்கிணை" },
    { "It will be recreated from the standard settings during prebuild or avatar build.", "முன்கட்டமைப்பு அல்லது அவதார் கட்டமைப்பின்போது வழக்கமான அமைப்புகளிலிருந்து மீண்டும் உருவாக்கப்படும்." },
    { "Item {1} ({2}) in {0} has no Motion Time parameter name.", "{0}-இன் உருப்படி {1} ({2})-க்கு Motion Time அளபுருப் பெயர் இல்லை." },
    { "Item {1} ({2}) in {0} has no animation.", "{0}-இன் உருப்படி {1} ({2})-க்கு அசைவூட்டம் இல்லை." },
    { "Item {1} ({2}) in {0} uses a Legacy animation.", "{0}-இன் உருப்படி {1} ({2}) Legacy அசைவூட்டத்தைப் பயன்படுத்துகிறது." },
