    { "Could not identify VRChat's default idle animation. Check the VRChat SDK.", "Không xác định được hoạt ảnh chờ mặc định của VRChat. Hãy kiểm tra VRChat SDK." },
    { "Could not identify the owning scene.", "Không xác định được scene sở hữu." },
    { "Could not isolate the breathing Controller in a copy for generation.", "Không thể tách Controller nhịp thở thành bản sao dùng để tạo." },
    { "Could not load prefab [PS042]", "Không tải được prefab [PS042]" },
    { "Could not load preset", "Không tải được thiết lập sẵn" },
    { "Could not load the preset list. Choose Reload to try again:", "Không tải được danh sách thiết lập sẵn. Chọn Tải lại để thử lại:" },
    { "Could not measure RootT displacement for roll-over head centering.", "Không đo được độ dịch chuyển RootT để căn giữa đầu khi lật người." },
    { "Could not measure a valid fixed length from the avatar scale.", "Không đo được chiều dài cố định hợp lệ từ tỉ lệ avatar." },
    { "Could not measure a valid length between {0} and {1}.", "Không đo được chiều dài hợp lệ giữa {0} và {1}." },
    { "Could not measure the depth difference between Head and Viewpoint. Check View Position and the avatar scale.", "Không đo được chênh lệch độ sâu giữa Head và Viewpoint. Kiểm tra View Position và tỉ lệ avatar." },
